using System.IO;using UnityEditor;using UnityEditor.Build.Reporting;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
public static class StreetLegendBuildTools{
const string Menu="Assets/Scenes/StreetLegend_MainMenu.unity",ScenePath="Assets/Scenes/Level1_Hotel_Prototype.unity",Output="Builds/Android/StreetLegend.apk";
[MenuItem("Street Legend/Validate Hotel Prototype")]public static void ValidateHotelPrototype(){if(!File.Exists(ScenePath)){Debug.LogError("Hotel scene missing; build it first.");return;}EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Single);int e=0;e+=Req("Wanimoo Player",typeof(PrototypeFighterController),typeof(CharacterController),typeof(PrototypeMobileHUD));e+=Req("Hotel Enforcer",typeof(PrototypeOpponent),typeof(CharacterController));e+=Req("Prototype Camera",typeof(Camera),typeof(PrototypeCameraFollow));e+=Req("Voice-Only Commentator",typeof(PrototypeCommentatorManager),typeof(AudioSource));e+=Req("Match Manager",typeof(PrototypeMatchManager));e+=Req("Hotel Floor",typeof(Collider));e+=Req("Rear Hotel Wall",typeof(Collider));e+=Req("Left Hotel Wall",typeof(Collider));e+=Req("Right Hotel Wall",typeof(Collider));if(e==0)Debug.Log("Structural validation passed (not runtime/device testing).");else Debug.LogError("Validation failed: "+e);}
static int Req(string n,params System.Type[] ts){var g=GameObject.Find(n);if(!g){Debug.LogError("Missing "+n);return 1;}int e=0;foreach(var t in ts)if(!g.GetComponent(t)){Debug.LogError(n+" missing "+t.Name);e++;}return e;}
[MenuItem("Street Legend/Build Android APK")]public static void BuildAndroidApk(){if(!File.Exists(Menu)||!File.Exists(ScenePath)){EditorUtility.DisplayDialog("Street Legend","Build both Main Menu and Hotel scenes first.","OK");return;}if(EditorUserBuildSettings.activeBuildTarget!=BuildTarget.Android&&!EditorUserBuildSettings.SwitchActiveBuildTarget(BuildTargetGroup.Android,BuildTarget.Android)){EditorUtility.DisplayDialog("Street Legend","Install Android Build Support, SDK, NDK and OpenJDK.","OK");return;}var d=Path.GetDirectoryName(Output);if(!Directory.Exists(d))Directory.CreateDirectory(d);EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(Menu,true),new EditorBuildSettingsScene(ScenePath,true)};PlayerSettings.Android.targetArchitectures=AndroidArchitecture.ARM64;PlayerSettings.defaultInterfaceOrientation=UIOrientation.LandscapeLeft;var o=new BuildPlayerOptions{scenes=new[]{Menu,ScenePath},locationPathName=Output,target=BuildTarget.Android,options=BuildOptions.None};var r=BuildPipeline.BuildPlayer(o);if(r.summary.result==BuildResult.Succeeded)Debug.Log("APK BUILD SUCCEEDED: "+Path.GetFullPath(Output)+"; device QA required.");else Debug.LogError("APK build failed: "+r.summary.result);}}